    test("ordinary Player outbox is self-scoped and uses current versions",[]{Fixture f;auto binding=f.bind();f.publicFeatures();auto out=dto<EcPhase2Submission>();auto credit=f.mutation(binding.caller_context,f.aliceJoin.player_id,f.owner,EC_P2_OP_ASSET_ADD,500,{80,81});require(binding.scoped_api->submit_mutation(&credit,&out)==EC_OK,"Credit event");auto oldRequest=credit.meta.request_id;auto transfer=f.mutation(binding.caller_context,f.aliceJoin.player_id,f.alice,EC_P2_OP_TRANSFER,100,{82,83},EC_P2_ASSET_MONEY,f.bobJoin.player_id);require(binding.scoped_api->submit_mutation(&transfer,&out)==EC_OK,"Transfer events");auto scope=f.mutation(binding.caller_context,f.aliceJoin.player_id,f.alice,EC_P2_OP_OUTBOX_READ,0,{84,85},0);EcPhase2OutboxRequest request{};request.meta=scope.meta;request.meta.struct_size=sizeof(request);request.limit=100;std::array<EcPhase2OutboxEvent,100> rows{};auto buffer=dto<EcPhase2OutboxBuffer>();buffer.data=rows.data();buffer.capacity=100;require(binding.scoped_api->read_outbox(&request,&buffer)==EC_OK&&buffer.count==2,"Only Alice rows");for(unsigned i=0;i<buffer.count;++i)require(same(rows[i].target,f.aliceJoin.player_id)&&rows[i].authoritative_balance==400&&rows[i].account_revision&&rows[i].occurred_at_unix_ms,"Current-authority event snapshot");require(same(rows[0].request_id,oldRequest),"Durable originating request ID");},groups);
