    test("outbox failure retries without treating publish as ack",[]{Fixture f;require(f.send("asset Alice money 100 outbox-failed reason").status==EC_OK,"Create outbox");f.publishFailure=true;require(f.api()->tick(f.api()->bridge_nonce,UINT64_MAX)==EC_OK&&f.published==1,"Failed publication recorded");for(unsigned i=0;i<100;++i)require(f.api()->tick(f.api()->bridge_nonce,0)==EC_OK,"Tick throttled");require(f.published==1,"No repeated tick publications");f.publishFailure=false;std::this_thread::sleep_for(std::chrono::milliseconds(1100));f.clock+=1100;require(f.api()->tick(f.api()->bridge_nonce,0)==EC_OK&&f.published==2,"Persistent retry succeeds");require(f.notices.back().event_cursor==f.notices.front().event_cursor,"Same durable event retried");f.runtime->disable();eternal::core::Core reader((f.root/"data"/"core.sqlite3").string(),"1000");require(reader.selfcheck().value.pendingDeliveries>0,"Publish success is not delivery acknowledgement");},groups);
